package com.example.starter.carbon;

import java.time.Instant;
import org.springframework.boot.context.properties.ConfigurationProperties;

/**
 * 履约配置。
 *
 * @param deadline 履约截止时刻（UTC）；恰在该时刻到达的申请仍受理，之后一律拒绝
 */
@ConfigurationProperties(prefix = "carbon.compliance")
public record CarbonProperties(Instant deadline) {
}

package com.example.starter.carbon;

import java.time.Clock;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

/**
 * 应用时钟配置：统一使用 UTC 时钟，测试中可替换为可控时钟以验证截止时刻口径。
 */
@Configuration
public class ClockConfig {

    /**
     * 提供 UTC 系统时钟。
     */
    @Bean
    public Clock carbonClock() {
        return Clock.systemUTC();
    }
}

package com.example.starter.carbon;

/**
 * 业务异常：携带 HTTP 状态码与稳定错误码，由全局异常处理器转换为统一错误响应。
 */
public class ApiException extends RuntimeException {

    private final int status;
    private final String code;

    public ApiException(int status, String code, String message) {
        super(message);
        this.status = status;
        this.code = code;
    }

    public int status() {
        return status;
    }

    public String code() {
        return code;
    }

    /**
     * 404：资源不存在。
     */
    public static ApiException notFound(String code, String message) {
        return new ApiException(404, code, message);
    }

    /**
     * 409：幂等键冲突（同 requestId 不同申请明细）。
     */
    public static ApiException conflict(String code, String message) {
        return new ApiException(409, code, message);
    }

    /**
     * 422：业务规则拒绝（超抵减上限、余额不足、逾期等），账户不发生任何变动。
     */
    public static ApiException unprocessable(String code, String message) {
        return new ApiException(422, code, message);
    }
}

